#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> A_vals(3), B_vals(3);
    for (int i = 0; i < 3; ++i) cin >> A_vals[i];
    for (int i = 0; i < 3; ++i) cin >> B_vals[i];

    vector<int> A_orig = A_vals;
    vector<int> B_orig = B_vals;

    auto max_win = [](vector<int> A_list, vector<int> B_list) {
        int total = 0;
        for (int i = 0; i < 3; ++i) {
            int opponent_idx = (i + 1) % 3;
            int wins = min(A_list[i], B_list[opponent_idx]);
            A_list[i] -= wins;
            B_list[opponent_idx] -= wins;
            total += wins;
        }
        return total;
    };

    auto max_loss = [](vector<int> A_list, vector<int> B_list) {
        vector<vector<int>> move_pairs = {{0, 2}, {1, 0}, {2, 1}, {0, 0}, {1, 1}, {2, 2}};
        vector<vector<int>> all_permutations;
        // Generate all permutations of move_pairs
        std::sort(move_pairs.begin(), move_pairs.end());
        do {
            all_permutations.push_back(move_pairs);
        } while (std::next_permutation(move_pairs.begin(), move_pairs.end()));

        int max_loss_value = 0;
        for (const auto& perm : all_permutations) {
            vector<int> A_copy = A_list;
            vector<int> B_copy = B_list;
            vector<int> losses(3, 0);
            for (const auto& move : perm) {
                int loss_amount = std::min(A_copy[move[0]], B_copy[move[1]]);
                A_copy[move[0]] -= loss_amount;
                B_copy[move[1]] -= loss_amount;
                losses[move[0]] += loss_amount;
            }
            int total_loss = std::accumulate(losses.begin(), losses.end(), 0);
            if (total_loss > max_loss_value) {
                max_loss_value = total_loss;
            }
        }
        return max_loss_value;
    };

    cout << n - max_loss(A_orig, B_orig) << " " << max_win(A_vals, B_vals) << "\n";

    return 0;
}
